"""v2.8 showcase must be generated by live verified business API, deterministically."""
import tempfile
from pathlib import Path
import unittest
from examples.run_r3_nodewise_adjustment import write

class NodewiseShowcaseV28(unittest.TestCase):
    def test_300_node_live_replayed_cases(self):
        with tempfile.TemporaryDirectory() as a,tempfile.TemporaryDirectory() as b:
            ja,ha,da=write(Path(a));jb,hb,db=write(Path(b))
            self.assertEqual(ja.read_bytes(),jb.read_bytes())
            self.assertEqual(ha.read_bytes(),hb.read_bytes())
            self.assertEqual(da['nodes'],300)
            self.assertEqual(da['case_counts'],{'POINT':6,'NEEDS_INPUT':4,'UNSUPPORTED':1})
            self.assertTrue(all(c['summary']['identification'] is not None
                for c in da['cases'] if c['status']=='POINT'))
            self.assertTrue(all(c['summary']['identification'] is None
                for c in da['cases'] if c['status']!='POINT'))
            self.assertTrue(all(c['summary']['identification']['verification_status']=='VERIFIED'
                for c in da['cases'] if c['status']=='POINT'))
            self.assertIsNone(da['finite_sample_effect_values'])
            self.assertIsNone(da['numeric_policy_values'])
            self.assertIn('不是销售数值估计',ha.read_text(encoding='utf-8'))

    def test_ambiguous_observational_data_do_not_identify_without_exchangeability(self):
        # Two worlds, same observed P(T,Yobs)={(0,0):1/2,(1,1):1/2}.
        # World A: Y(0)=0,Y(1)=1. World B: latent U=T, Y(0)=Y(1)=U.
        # At least a singleton C_i stratum is allowed; P(T) factorizes
        # across nodes if independent U_i. Yet E[Y_i(1)] differs.
        from fractions import Fraction
        observed_a={(0,0):Fraction(1,2),(1,1):Fraction(1,2)}
        observed_b={(t,t):Fraction(1,2) for t in (0,1)}
        self.assertEqual(observed_a,observed_b)
        self.assertNotEqual(Fraction(1),Fraction(1,2))
        # Therefore A4 known p(T|X) does NOT logically supply the A5 license.

if __name__=='__main__':unittest.main()
